	if r.closed {
		return ErrStopped
	}
	if len(r.queue) >= r.queueSize {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and jobs that have
// not started are not started. It waits for running jobs to finish. If ctx ends first, it cancels the
// context of every running job, waits for them to return and returns ctx.Err(). It returns nil when every
// running job finished before ctx ended. A call after the first returns nil at once, without waiting.
func (r *Runner) Shutdown(ctx context.Context) error {
	first := false
	r.shutdown.Do(func() { first = true })
	if !first {
		return nil
	}

	r.mu.Lock()
	r.closed = true
	r.cond.Broadcast()
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	if len(r.active) == 0 {
		// Every job finished before ctx ended; the workers are just exiting.
		r.mu.Unlock()
		<-done
		return nil
	}
	for _, run := range r.active {
		run.canceled = true
		run.cancel()
	}
	r.mu.Unlock()
	<-done
	return ctx.Err()
}

// Stop stops the runner like Shutdown, with a 30 second timeout.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these
// are the queued jobs that have not started. After Shutdown they are the jobs that were never started,
// followed by the jobs whose context Shutdown cancelled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	abandon := slices.Clone(r.abandon)
	slices.SortFunc(abandon, func(a, b entry) int { return a.seq - b.seq })
	pending := make([]Job, 0, len(r.queue)+len(abandon))
	for _, e := range r.queue {
		pending = append(pending, e.job)
	}
	for _, e := range abandon {
		pending = append(pending, e.job)
	}
	return pending
}

// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"slices"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// entry is a job with its position in the enqueue order.
type entry struct {
	seq int
	job Job
}

// running is a job that a worker is executing.
type running struct {
	cancel   context.CancelFunc
	canceled bool // Shutdown cancelled the job's context
}

// Runner runs jobs on its workers.
type Runner struct {
	workers   int
	queueSize int
	log       *slog.Logger

	mu       sync.Mutex
	cond     *sync.Cond
	queue    []entry           // enqueued jobs that have not started, in enqueue order
	seq      int               // sequence number of the last enqueued job
	closed   bool              // Shutdown has been called
	active   map[int]*running  // jobs being executed, by seq
	abandon  []entry           // jobs cancelled by Shutdown that returned an error
	wg       sync.WaitGroup    // workers
	shutdown sync.Once         // makes the first Shutdown call the only one that waits
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if queueSize < 0 {
		queueSize = 0
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{workers: workers, queueSize: queueSize, log: log, active: map[int]*running{}}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing after Shutdown.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		r.mu.Lock()
		for len(r.queue) == 0 && !r.closed {
			r.cond.Wait()
		}
		if r.closed {
			r.mu.Unlock()
			return
		}
		e := r.queue[0]
		r.queue[0] = entry{}
		r.queue = r.queue[1:]
		ctx, cancel := context.WithCancel(context.Background())
		run := &running{cancel: cancel}
		r.active[e.seq] = run
		r.mu.Unlock()

		err, ok := r.call(ctx, e.job)
		cancel()

		r.mu.Lock()
		delete(r.active, e.seq)
		if run.canceled && err != nil && ok {
			r.abandon = append(r.abandon, e)
		}
		r.mu.Unlock()
	}
}

// call runs j and recovers a panic. ok is false when j panicked, so the job is not run again.
func (r *Runner) call(ctx context.Context, j Job) (err error, ok bool) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p)
			err, ok = nil, false
		}
	}()
	if err := j.Run(ctx); err != nil {
		r.log.Error("job failed", "job", j.Name, "err", err)
		return err, true
	}
	return nil, true
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	if len(r.queue) >= r.queueSize {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and jobs that have
// not started are not started. It waits for running jobs to finish. If ctx ends first, it cancels the
// context of every running job, waits for them to return and returns ctx.Err(). It returns nil when every
// running job finished before ctx ended. A call after the first returns nil at once, without waiting.
func (r *Runner) Shutdown(ctx context.Context) error {
	first := false
	r.shutdown.Do(func() { first = true })
	if !first {
		return nil
	}

	r.mu.Lock()
	r.closed = true
	r.cond.Broadcast()
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	if len(r.active) == 0 {
		// Every job finished before ctx ended; the workers are just exiting.
		r.mu.Unlock()
		<-done
		return nil
	}
	for _, run := range r.active {
		run.canceled = true
		run.cancel()
	}
	r.mu.Unlock()
	<-done
	return ctx.Err()
}

// Stop stops the runner like Shutdown, with a 30 second timeout.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these
// are the queued jobs that have not started. After Shutdown they are the jobs that were never started,
// followed by the jobs whose context Shutdown cancelled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	abandon := slices.Clone(r.abandon)
	slices.SortFunc(abandon, func(a, b entry) int { return a.seq - b.seq })
	pending := make([]Job, 0, len(r.queue)+len(abandon))
	for _, e := range r.queue {
		pending = append(pending, e.job)
	}
	for _, e := range abandon {
		pending = append(pending, e.job)
	}
	return pending
}

