package jobs

import (
	"context"
	"errors"
	"slices"
	"sync"
	"testing"
	"time"
)

func TestRunnerRunsJobs(t *testing.T) {
	r := NewRunner(3, 10, nil)
	r.Start()
	var mu sync.Mutex
	done := map[string]bool{}
	var wg sync.WaitGroup
	for _, name := range []string{"a", "b", "c", "d", "e"} {
		wg.Add(1)
		if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
			defer wg.Done()
			mu.Lock()
			done[name] = true
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	finished := make(chan struct{})
	go func() { wg.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("jobs did not run")
	}
	if len(done) != 5 {
		t.Fatalf("done = %v", done)
	}
}

func TestEnqueueWhenFull(t *testing.T) {
	r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
	job := Job{Name: "x", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("err = %v, want ErrQueueFull", err)
	}
}

func TestEnqueueAfterShutdownReturnsErrStopped(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	late := Job{Name: "late", Run: func(context.Context) error {
		t.Error("late job ran")
		return nil
	}}
	if err := r.Enqueue(late); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	finished := make(chan struct{})
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		close(started)
		<-release
		close(finished)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	errc := make(chan error, 1)
	go func() { errc <- r.Shutdown(context.Background()) }()
	select {
	case <-errc:
		t.Fatal("Shutdown returned while a job was running")
	case <-time.After(50 * time.Millisecond):
	}
	close(release)
	if err := <-errc; err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	select {
	case <-finished:
	default:
		t.Fatal("Shutdown returned before the running job finished")
	}
}

func TestShutdownCancelsRunningJobsWhenContextEnds(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	if err := r.Enqueue(Job{Name: "stuck", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		return ctx.Err()
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"stuck"}) {
		t.Fatalf("pending = %v, want [stuck]", got)
	}
}

func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	ran := make(chan string, 10)
	if err := r.Enqueue(Job{Name: "first", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done() // returns nil once cancelled, so it is not pending
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"second", "third"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error {
			ran <- name
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	<-started

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	select {
	case name := <-ran:
		t.Fatalf("queued job %s was started", name)
	default:
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"second", "third"}) {
		t.Fatalf("pending = %v, want [second third]", got)
	}
}

func TestPendingListsQueuedJobsInEnqueueOrder(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending before Shutdown = %v, want [a b c]", got)
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending after Shutdown = %v, want [a b c]", got)
	}
}

func TestSecondShutdownReturnsAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		close(started)
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	errc := make(chan error, 1)
	go func() { errc <- r.Shutdown(context.Background()) }()

	second := make(chan error, 1)
	go func() { second <- r.Shutdown(context.Background()) }()
	select {
	case err := <-second:
		if err != nil {
			t.Fatalf("second Shutdown = %v, want nil", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("second Shutdown blocked")
	}

	close(release)
	if err := <-errc; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
	stopped := make(chan struct{})
	go func() { r.Stop(); close(stopped) }()
	select {
	case <-stopped:
	case <-time.After(5 * time.Second):
		t.Fatal("Stop after Shutdown blocked")
	}
}

func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	boomRuns := 0
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error {
		boomRuns++
		panic("boom")
	}}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("job after the panic did not run")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if boomRuns != 1 {
		t.Fatalf("panicking job ran %d times, want 1", boomRuns)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

// names returns the names of jobs, for comparing Pending results.
func names(jobs []Job) []string {
	var out []string
	for _, j := range jobs {
		out = append(out, j.Name)
	}
	return out
}

